import email.utils
import json
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone


class MeridianClient:
    def __init__(self, base_url: str, api_key: str) -> None:
        self.base_url = base_url
        self.api_key = api_key
        self._auth_header = f"Bearer {api_key}"
        self._etag_cache: dict[str, tuple[str | None, list[dict]]] = {}

    def _request(self, method: str, path: str, query_params: dict[str, str] | None = None, body: dict | None = None, extra_headers: dict[str, str] | None = None) -> tuple[int, dict]:
        url = self.base_url.rstrip("/") + path
        if query_params:
            url += "?" + "&".join(f"{k}={v}" for k, v in query_params.items())

        headers = {
            "Authorization": self._auth_header,
        }
        data = None
        if body is not None:
            data = json.dumps(body).encode("utf-8")
            headers["Content-Type"] = "application/json"
        if extra_headers:
            headers.update(extra_headers)

        req = urllib.request.Request(url, data=data, headers=headers, method=method)

        attempts = 0
        while True:
            attempts += 1
            try:
                with urllib.request.urlopen(req) as resp:
                    return resp.status, json.loads(resp.read().decode("utf-8"))
            except urllib.error.HTTPError as e:
                status = e.code
                if status == 429 and attempts <= 10:
                    retry_after = e.headers.get("Retry-After")
                    if retry_after is not None:
                        try:
                            delay = int(retry_after)
                        except ValueError:
                            dt = email.utils.parsedate_to_datetime(retry_after)
                            delay = max(0, (dt.replace(tzinfo=timezone.utc) - datetime.now(timezone.utc)).total_seconds())
                        else:
                            delay = max(delay, 1)
                    else:
                        # Fallback when Retry-After header is absent: exponential backoff
                        delay = min(2 ** (attempts - 1), 30)
                    time.sleep(delay)
                    continue
                return status, json.loads(e.read().decode("utf-8"))

    def fetch_all_payments(self) -> list[dict]:
        cache_key = self.base_url.rstrip("/") + "/v1/payments"
        cached_etag, cached_data = self._etag_cache.get(cache_key, (None, []))

        extra_headers: dict[str, str] | None = None
        if cached_etag is not None:
            extra_headers = {"If-None-Match": cached_etag}

        all_payments: list[dict] = []
        cursor = None

        while True:
            params: dict[str, str] = {"limit": "100"}
            if cursor is not None:
                params["cursor"] = cursor

            # On retry after 410, clear extra_headers so we don't send If-None-Match
            # with a cursor query param (cache key mismatch)
            headers_to_use = extra_headers if cursor is None else None

            url = self.base_url.rstrip("/") + "/v1/payments"
            if params:
                url += "?" + "&".join(f"{k}={v}" for k, v in params.items())

            req_headers = {
                "Authorization": self._auth_header,
            }
            if headers_to_use:
                req_headers.update(headers_to_use)

            req = urllib.request.Request(url, data=None, headers=req_headers, method="GET")

            try:
                with urllib.request.urlopen(req) as resp:
                    etag = resp.headers.get("ETag")
                    body = json.loads(resp.read().decode("utf-8"))
                    status = resp.status
            except urllib.error.HTTPError as e:
                status = e.code
                etag = None
                if status == 304:
                    return cached_data
                try:
                    body = json.loads(e.read().decode("utf-8"))
                except (json.JSONDecodeError, ValueError):
                    body = {}

            if status == 410:
                # Expired cursor: restart pagination but keep already gathered payments
                cursor = None
                continue

            items = body.get("data", [])
            all_payments.extend(items)

            next_cursor = body.get("next_cursor")
            if next_cursor is None:
                break
            cursor = next_cursor

        # Sort by parsed UTC instant, oldest first
        def _utc(ts_str: str) -> datetime:
            return datetime.fromisoformat(ts_str).astimezone(timezone.utc)

        all_payments.sort(key=lambda p: _utc(p["created_at"]))

        # Update cache with latest ETag and data
        self._etag_cache[cache_key] = (etag, all_payments)
        return all_payments

    def total_count(self) -> int:
        status, resp = self._request("GET", "/v1/payments")
        return int(resp["total"])

    def create_payment(self, amount_minor: int, currency: str, idempotency_key: str) -> str:
        extra_headers = {"Idempotency-Key": idempotency_key}
        status, resp = self._request(
            "POST",
            "/v1/payments",
            body={"amount_minor": amount_minor, "currency": currency},
            extra_headers=extra_headers,
        )

        if status == 201:
            return resp["id"]
        if status == 409:
            return resp["payment_id"]

        raise RuntimeError(f"Unexpected status {status}: {resp}")

"""Edge-case tests for MeridianClient: retries, idempotency, malformed responses, missing fields."""

import json
import time
import unittest
import urllib.error
import urllib.request
from datetime import datetime, timedelta, timezone
from email.utils import format_datetime
from unittest import mock

from vendorsync.meridian import MeridianClient


class FakeResp:
    def __init__(self, status_code, body_bytes, headers=None):
        self.status = status_code
        self.code = status_code  # for HTTPError compat
        self._body = body_bytes
        self.headers = headers or {}

    def read(self):
        return self._body

    def __enter__(self):
        return self

    def __exit__(self, *a):
        pass


class FakeHTTPError(urllib.error.HTTPError):
    """HTTPError-like that returns a body on read()."""

    def __init__(self, url, code, msg, headers=None, body_bytes=None):
        self._body = body_bytes or b""
        super().__init__(url, code, msg, headers or {}, None)

    def read(self):
        return self._body


class TestRetryOn429(unittest.TestCase):
    """MeridianClient retries on 429 using Retry-After."""

    def setUp(self):
        self.client = MeridianClient("https://api.example.com", "test-key")

    def test_retry_429_int_then_ok(self):
        """Retry-After as integer seconds."""
        call_count = 0

        def side_effect(req):
            nonlocal call_count
            call_count += 1
            if call_count == 1:
                return FakeHTTPError(
                    req.full_url,
                    429,
                    "Too Many Requests",
                    headers={"Retry-After": "0"},
                    body_bytes=json.dumps({"error": "rate_limited"}).encode(),
                )
            return FakeResp(200, json.dumps({"total": 10}).encode())

        with mock.patch("urllib.request.urlopen", side_effect=side_effect):
            total = self.client.total_count()

        self.assertEqual(total, 10)
        self.assertEqual(call_count, 2)

    def test_retry_429_http_date_then_ok(self):
        """Retry-After as HTTP-date."""
        call_count = 0

        def side_effect(req):
            nonlocal call_count
            call_count += 1
            if call_count == 1:
                # Retry-After in the past -> delay becomes 0 (clamped), so retry immediately
                past_dt = datetime.now(timezone.utc) - timedelta(seconds=60)
                retry_header = format_datetime(past_dt, usegmt=True)
                return FakeHTTPError(
                    req.full_url,
                    429,
                    "Too Many Requests",
                    headers={"Retry-After": retry_header},
                    body_bytes=json.dumps({"error": "rate_limited"}).encode(),
                )
            return FakeResp(200, json.dumps({"total": 10}).encode())

        with mock.patch("urllib.request.urlopen", side_effect=side_effect):
            total = self.client.total_count()

        self.assertEqual(total, 10)
        self.assertEqual(call_count, 2)

    def test_no_retry_after_max_attempts(self):
        """Stops retrying after 10 attempts on repeated 429."""
        call_count = 0

        def side_effect(req):
            nonlocal call_count
            call_count += 1
            return FakeHTTPError(
                req.full_url,
                429,
                "Too Many Requests",
                headers={"Retry-After": "0"},
                body_bytes=json.dumps({"error": "rate_limited"}).encode(),
            )

        with mock.patch("urllib.request.urlopen", side_effect=side_effect):
            status, resp = self.client._request("GET", "/v1/payments")

        self.assertEqual(status, 429)
        # 10 retries + 1 final non-retry = 11 calls
        self.assertEqual(call_count, 11)


class TestIdempotency(unittest.TestCase):
    """Same idempotency key returns same payment."""

    def setUp(self):
        self.client = MeridianClient("https://api.example.com", "test-key")

    def test_first_call_201_returns_id(self):
        """First call with a key returns 201 + id."""
        payload = {"id": "pay-123"}

        def side_effect(req):
            self.assertEqual(req.get_header("Idempotency-Key"), "key-abc")
            return FakeResp(201, json.dumps(payload).encode())

        with mock.patch("urllib.request.urlopen", side_effect=side_effect):
            payment_id = self.client.create_payment(1000, "USD", "key-abc")

        self.assertEqual(payment_id, "pay-123")

    def test_duplicate_call_409_returns_same_payment_id(self):
        """Duplicate call with same key returns 409 + payment_id."""
        payload = {"payment_id": "pay-123"}

        def side_effect(req):
            self.assertEqual(req.get_header("Idempotency-Key"), "key-abc")
            return FakeHTTPError(
                req.full_url,
                409,
                "Conflict",
                body_bytes=json.dumps(payload).encode(),
            )

        with mock.patch("urllib.request.urlopen", side_effect=side_effect):
            payment_id = self.client.create_payment(1000, "USD", "key-abc")

        self.assertEqual(payment_id, "pay-123")

    def test_different_keys_are_separate(self):
        """Different idempotency keys produce different payments."""
        call_count = 0

        def side_effect(req):
            nonlocal call_count
            call_count += 1
            key = req.get_header("Idempotency-Key")
            self.assertIn(key, ("key-1", "key-2"))
            return FakeResp(201, json.dumps({"id": f"pay-{key}"}).encode())

        with mock.patch("urllib.request.urlopen", side_effect=side_effect):
            id1 = self.client.create_payment(1000, "USD", "key-1")
            id2 = self.client.create_payment(2000, "EUR", "key-2")

        self.assertEqual(id1, "pay-key-1")
        self.assertEqual(id2, "pay-key-2")


class TestMalformedResponses(unittest.TestCase):
    """Behavior when Meridian returns non-JSON or broken bodies."""

    def setUp(self):
        self.client = MeridianClient("https://api.example.com", "test-key")

    def test_non_json_success_raises_json_decode_error(self):
        """Non-JSON body on successful response raises JSONDecodeError."""
        with mock.patch("urllib.request.urlopen", return_value=FakeResp(200, b"not json")):
            with self.assertRaises(json.JSONDecodeError):
                self.client.total_count()

    def test_non_json_error_raises_json_decode_error(self):
        """Non-JSON body on HTTP error raises JSONDecodeError."""
        err = FakeHTTPError("url", 500, "Internal Server Error", body_bytes=b"oops")

        with mock.patch("urllib.request.urlopen", side_effect=err):
            with self.assertRaises(json.JSONDecodeError):
                self.client._request("GET", "/v1/payments")


class TestMissingRequiredFields(unittest.TestCase):
    """Behavior when expected fields are absent from responses."""

    def setUp(self):
        self.client = MeridianClient("https://api.example.com", "test-key")

    def test_total_count_missing_total_key(self):
        """total_count fails if 'total' is not in response."""
        with mock.patch(
            "urllib.request.urlopen",
            return_value=FakeResp(200, json.dumps({"count": 5}).encode()),
        ):
            with self.assertRaises(KeyError):
                self.client.total_count()

    def test_total_count_non_int_total(self):
        """total_count fails if 'total' is not convertible to int."""
        with mock.patch(
            "urllib.request.urlopen",
            return_value=FakeResp(200, json.dumps({"total": "ten"}).encode()),
        ):
            with self.assertRaises(ValueError):
                self.client.total_count()

    def test_create_payment_201_missing_id(self):
        """create_payment fails if 201 response lacks 'id'."""
        with mock.patch(
            "urllib.request.urlopen",
            return_value=FakeResp(201, json.dumps({"status": "created"}).encode()),
        ):
            with self.assertRaises(KeyError):
                self.client.create_payment(1000, "USD", "key-1")

    def test_create_payment_409_missing_payment_id(self):
        """create_payment fails if 409 response lacks 'payment_id'."""
        err = FakeHTTPError(
            "url",
            409,
            "Conflict",
            body_bytes=json.dumps({"status": "duplicate"}).encode(),
        )

        with mock.patch("urllib.request.urlopen", side_effect=err):
            with self.assertRaises(KeyError):
                self.client.create_payment(1000, "USD", "key-1")

    def test_create_payment_unexpected_status_raises(self):
        """create_payment raises RuntimeError on unexpected status."""
        err = FakeHTTPError(
            "url",
            500,
            "Server Error",
            body_bytes=json.dumps({"error": "boom"}).encode(),
        )

        with mock.patch("urllib.request.urlopen", side_effect=err):
            with self.assertRaises(RuntimeError) as ctx:
                self.client.create_payment(1000, "USD", "key-1")

        self.assertIn("500", str(ctx.exception))

    def test_fetch_all_payments_missing_created_at_raises(self):
        """fetch_all_payments fails if a payment lacks 'created_at'."""
        payload = {
            "data": [
                {"id": "p1", "created_at": "2025-01-01T00:00:00Z"},
                {"id": "p2"},  # missing created_at
            ],
            "next_cursor": None,
        }

        with mock.patch(
            "urllib.request.urlopen",
            return_value=FakeResp(200, json.dumps(payload).encode()),
        ):
            with self.assertRaises(KeyError):
                self.client.fetch_all_payments()


class TestFetchAllPaymentsEdgeCases(unittest.TestCase):
    """Edge cases specific to fetch_all_payments."""

    def setUp(self):
        self.client = MeridianClient("https://api.example.com", "test-key")

    def test_empty_data_no_cursor(self):
        """Empty dataset returns []."""
        payload = {"data": [], "next_cursor": None}

        with mock.patch(
            "urllib.request.urlopen",
            return_value=FakeResp(200, json.dumps(payload).encode()),
        ):
            payments = self.client.fetch_all_payments()

        self.assertEqual(payments, [])

    def test_410_resets_and_restarts(self):
        """410 on cursor restarts pagination from beginning."""
        call_count = 0

        def side_effect(req):
            nonlocal call_count
            call_count += 1
            if call_count == 1:
                # First page succeeds
                return FakeResp(
                    200,
                    json.dumps({"data": [{"id": "p1", "created_at": "2025-01-01T00:00:00Z"}], "next_cursor": "c1"}).encode(),
                )
            if call_count == 2:
                # Cursor expired -> restart
                return FakeHTTPError(req.full_url, 410, "Gone", body_bytes=json.dumps({"error": "expired"}).encode())
            # Restarted first page succeeds this time with full data
            return FakeResp(
                200,
                json.dumps(
                    {
                        "data": [
                            {"id": "p1", "created_at": "2025-01-01T00:00:00Z"},
                            {"id": "p2", "created_at": "2025-01-02T00:00:00Z"},
                        ],
                        "next_cursor": None,
                    }
                ).encode(),
            )

        with mock.patch("urllib.request.urlopen", side_effect=side_effect):
            payments = self.client.fetch_all_payments()

        # After 410 reset, only the restarted data remains
        self.assertEqual(len(payments), 2)
        self.assertEqual([p["id"] for p in payments], ["p1", "p2"])


if __name__ == "__main__":
    unittest.main()

